    await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
    expect(await ui.addPerson(pg_uma, {"name": "pam", "grade": "A"})).toBeNull();
    expect(await ui.addPerson(pg_uma, {"name": "PAMMY", "grade": "A"})).toBeNull();
